const fs = require('fs');
const os = require('os');
const path = require('path');
const chokidar = require('chokidar');
function mk() { const d = fs.mkdtempSync(path.join(os.tmpdir(), 'choki-')); fs.writeFileSync(path.join(d,'a.md'),'#a'); return d; }
async function once(persistent, delayMs) {
  const w = chokidar.watch([mk()], { ignoreInitial: true, persistent });
  await new Promise(r => w.on('ready', r));
  await w.close();
  if (delayMs > 0) await new Promise(r => setTimeout(r, delayMs));
  else await new Promise(r => setImmediate(r));
  const n = process._getActiveHandles().filter(h => h.constructor && h.constructor.name === 'FSWatcher').length;
  return n;
}
