  for (const delay of [0, 1, 5, 10, 20]) {
    // run several times
    let max = 0;
    for (let i=0;i<5;i++){ max = Math.max(max, await once(true, delay)); }
    console.log('delay='+delay+'ms max FSWatcher leftover:', max);
  }
}
main();
EOF
