import { startServer } from '../src/server';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import * as http from 'http';

function tmpdir() { return fs.mkdtempSync(path.join(os.tmpdir(), 'sample-')); }

it('sample', async () => {
  const root = tmpdir();
  const content = path.join(root, 'content');
  fs.mkdirSync(content, { recursive: true });
  fs.writeFileSync(path.join(content, 'a.md'), '# A\n');
  const dev = startServer({ contentDir: content, outputDir: path.join(root, 'dist'), port: 0 });
  await new Promise<void>((r) => dev.server.once('listening', r));
  const addr = dev.server.address();
  const port = typeof addr === 'object' && addr ? addr.port : 0;
  await new Promise<void>((resolve, reject) => {
    http.get(`http://127.0.0.1:${port}/`, { agent: false }, (res) => { res.resume(); res.on('end', resolve); }).on('error', reject);
  });
  // sample ref'd handles/requests for 3s every 5ms
  let sawRefd = false;
  const samples: string[] = [];
  for (let i = 0; i < 600; i++) {
    const refd = (process as any)._getActiveHandles().filter((h: any) => typeof h.hasRef === 'function' && h.hasRef());
    const reqs = (process as any)._getActiveRequests().length;
    if (refd.length > 0 || reqs > 0) {
      sawRefd = true;
      const names = refd.map((h: any) => h.constructor && h.constructor.name).join(',');
      samples.push(`t=${i*5}ms refd=[${names}] reqs=${reqs}`);
    }
    await new Promise((r) => setTimeout(r, 5));
  }
  await dev.close();
  console.log('SAMPLE sawRefd=', sawRefd, 'sampleCount=', samples.length);
  if (sawRefd) console.log('SAMPLE first:', samples[0], 'last:', samples[samples.length-1]);
});
EOF
npx jest tests/_samplediag.test.ts 2>&1 | grep -E "SAMPLE" | head; rm -f tests/_samplediag.test.ts

